  const n = Math.sqrt(arr.length);

  // 将一维输入转为二维矩阵
  const matrix = new Array(n).fill(0).map(() => new Array(n).fill(0));

  // 将矩阵中所有感染区域位置记录到queue中,这里选择queue先进先出的原因是保证当天的感染区域并发扩散
