  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      matrix[i][j] = arr[i * n + j];
      if (matrix[i][j] === 1) queue.push([i, j]);
    }
  }

  // 全是感染区，或全是健康区
  if (queue.length === 0 || queue.length === arr.length) {
    return -1;
  }

  // 健康区个数
  let healthy = arr.length - queue.length;

  // 上下左右位置偏移量
  const offsets = [
    [-1, 0], // 上
    [1, 0], // 下
    [0, -1], // 左
    [0, 1], // 右
  ];

  // day用于统计感染全部花费的时间
  let day = 0;
  // 如果健康区个数为0，说明感染完了
  while (queue.length && healthy) {
    const newQueue = [];

    // 遍历完当前queue的所有感染区，即过去一天
    for (const [x, y] of queue) {
      for (let [offsetX, offsetY] of offsets) {
        const newX = x + offsetX;
        const newY = y + offsetY;

        if (
          newX >= 0 &&
          newX < n &&
          newY >= 0 &&
          newY < n &&
          matrix[newX][newY] === 0
        ) {
          healthy--;
          matrix[newX][newY] = 1;
          // 新增感染区加到newQue中，不影响queue的当前遍历
          newQueue.push([newX, newY]);
        }
      }
    }

    day++;
    queue = newQueue;
  }

  return day;
}

