#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>

#define MAX_SIZE 200

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();

void addLast_LinkedList(LinkedList *link, int ele);

int getResult(const int nums[], int nums_size);

int main() {
    int nums[MAX_SIZE * MAX_SIZE];
    int nums_size = 0;

    while (scanf("%d", &nums[nums_size++])) {
        if (getchar() != ',') break;
    }

    printf("%d\n", getResult(nums, nums_size));

    return 0;
}

int getResult(const int nums[], int nums_size) {
    // 题目说会输入n*n个值
    int n = (int) sqrt(nums_size);

    // 将一维arr输入转为二维矩阵matrix
    int matrix[MAX_SIZE][MAX_SIZE];

    // 将矩阵中所有感染区域位置记录到queue中,这里选择queue先进先出的原因是保证当天的感染区域并发扩散
    LinkedList *queue = new_LinkedList();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            matrix[i][j] = nums[i * n + j];

            if (matrix[i][j] == 1) {
                addLast_LinkedList(queue, i * n + j);
            }
        }
    }

    // 全是感染区，或全是健康区
    if (queue->size == 0 || queue->size == nums_size) {
        return -1;
    }

    // 健康区个数
    int healthy = nums_size - queue->size;

    // 上下左右偏移量
    int offsets[4][2] = {{-1, 0},
                         {1,  0},
                         {0,  -1},
                         {0,  1}};

    // day用于统计感染全部花费的时间
    int day = 0;

    // 如果健康区个数为0，说明感染完了
    while (queue->size > 0 && healthy > 0) {
        LinkedList *newQueue = new_LinkedList();

        // 遍历完当前queue的所有感染区，即过去一天
        ListNode *cur = queue->head;
        while (cur != NULL) {
            int x = cur->ele / n;
            int y = cur->ele % n;

            for (int i = 0; i < 4; i++) {
                int newX = x + offsets[i][0];
                int newY = y + offsets[i][1];

                if (newX >= 0 && newX < n && newY >= 0 && newY < n && matrix[newX][newY] == 0) {
                    matrix[newX][newY] = 1;
                    healthy--;
                    // 新增感染区加到newQue中，不影响queue的当前遍历
                    addLast_LinkedList(newQueue, newX * n + newY);
                }
            }

            cur = cur->next;
        }

        day++;
        queue = newQueue;
    }

    return day;
}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}
